const response=$input.first().json;
if(response.code!==200)throw new Error('Kie balance check failed; no generation requested.');
const raw=response.data;
const available=Number(typeof raw==='object'?(raw?.credits??raw?.balance??raw?.credit):raw);
if(!Number.isFinite(available))throw new Error('Kie balance format unknown; stopping before paid generation.');
// Planned: six Qwen2.1 1K images x 4, plus one Grok 6s video x 2.4.
if(available<40)throw new Error('Need 40 credits of available balance for the planned episode. Current balance: '+available);
return [{json:{available,expected_cost:38.4,max_planned_spend:40}}];

return (function buildStory() {
  const startDay = Date.UTC(2026, 10, 1);
  const today = new Date();
  const dayIndex = Math.max(0, Math.floor((Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),today.getUTCDate()) - startDay) / 86400000));
  const episodeNumber = dayIndex + 1;
  const mysteries = [
    ['The Mirror of Tomorrow','a mirror that reveals tomorrow','a missing hour from the future','the silver doorway'],
    ['The Clockwork Garden','a garden where clocks grow on vines','the flowers freezing in time','the copper gate'],
    ['The Library of Lost Days','a library holding forgotten tomorrows','pages disappearing from history','the book of blue light'],
    ['The City Above the Clouds','a city floating above purple clouds','the city slowly descending','the crystal bridge'],
    ['The Forgotten Star','a small star trapped in a snow globe','the night sky turning blank','the starlight chamber'],
    ['The Ocean of Memories','a blue ocean that reflects memories','the waves losing their colors','the luminous lighthouse'],
    ['The Door Without a Shadow','a door that casts no shadow','shadows moving on their own','the golden key'],
    ['The Train to Yesterday','a train that travels backward in time','the final station vanishing','the glowing railway switch'],
    ['The City of Sleeping Robots','a robot city in mysterious silence','every friendly robot losing power','the heartbeat generator'],
    ['The Compass of Wishes','a compass that points to impossible places','the compass spinning out of control','the secret North Tower'],
    ['The Moonlit Maze','a maze of silver moonbeams','the exit slowly dissolving','the moonstone arch'],
    ['The Painted Planet','a planet hidden inside a painting','its beautiful colors disappearing','the artist’s glowing brush']
  ];
  const places = ['an abandoned observatory','a glowing woodland','a secret clocktower','a floating science museum','a glass valley','an underground star station','a quiet mountain village','a shimmering seaside city','a mysterious old theater','a sky garden','a deserted amusement park','an impossible train station'];
  const clues = ['a tiny blue spiral','three blinking lights','a note written backward','a constellation shaped like a key','a musical tone that repeats twice','an arrow that only Pip can see','a silver feather','a reflection with no owner','a glowing geometric symbol','a whisper from the future','a clock that never ticks','a mysterious footprint'];
  const variants = ['a friendly new companion calls from the portal','another impossible doorway appears in the sky','the same strange symbol starts glowing on Pip','Mila hears a message from her future self','a new ticking sound echoes through the clouds','the rescued city reveals a second mystery'];
  const mystery = mysteries[dayIndex % mysteries.length];
  const place = places[Math.floor(dayIndex / mysteries.length) % places.length];
  const clue = clues[Math.floor(dayIndex / (mysteries.length * places.length)) % clues.length];
  const twist = variants[(dayIndex + Math.floor(dayIndex / 11)) % variants.length];
  const [name, discovery, danger, goal] = mystery;
  const style = 'High-quality cinematic 3D family science-fiction animation. Vertical 9:16. Consistent Mila and Pip designs. Detailed beautiful environments, soft cinematic lighting, expressive faces, clear action.';
  const scenes = [
    {scene_number:1,duration:15,scene_prompt:`At ${place}, Mila and Pip discover ${discovery}. Mila wears her familiar teal jacket and orange backpack. The mystery begins peacefully.`,animation_prompt:`Mila explores ${place} with Pip. The camera reveals ${discovery}. Narrator: "Something impossible is hiding in plain sight." Mila: "Pip, did you see that?" Pip: "I definitely did!"`},
    {scene_number:2,duration:15,scene_prompt:`Mila notices ${clue} beside ${discovery}. Pip scans it, projecting friendly glowing holograms.`,animation_prompt:`Mila follows ${clue}. Pip scans the unusual object. Pip: "This clue belongs to a different time!" Mila: "Then we need to find out why." Camera glides toward the clue.`},
    {scene_number:3,duration:15,scene_prompt:`Inside a vivid futuristic landscape, ${danger}. Mila and Pip stare in amazement; the world is still beautiful but urgently needs help.`,animation_prompt:`Show ${danger}. Mila gasps. Mila: "This place needs our help!" Pip: "And we might be running out of time!" Dramatic family-friendly adventure atmosphere.`},
    {scene_number:4,duration:15,scene_prompt:`A luminous holographic message displays ${goal} in the distance. Pip points toward a safe adventurous path through a spectacular 3D world.`,animation_prompt:`Pip projects a glowing map pointing to ${goal}. Pip: "I found our next clue!" Mila: "Great. Let's get there together!" Smooth orbiting camera reveals their route.`},
    {scene_number:5,duration:15,scene_prompt:`Mila and Pip cross a breathtaking landscape toward ${goal}, navigating harmless magical floating platforms and colorful energy ribbons.`,animation_prompt:`Mila jumps across safe illuminated platforms while Pip flies beside her. Pip: "Careful, Mila!" Mila: "I've got this!" Beautiful motion and a dynamic tracking shot.`},
    {scene_number:6,duration:15,scene_prompt:`Close to ${goal}, a glowing puzzle forms from ${clue}. Mila studies the pattern while Pip offers an enthusiastic hint.`,animation_prompt:`Mila and Pip solve a glowing mechanical puzzle together. Pip: "Try the pattern we saw before!" Mila: "You're right!" The pieces click gently into place.`},
    {scene_number:7,duration:15,scene_prompt:`The ${goal} lights up, reversing ${danger}. Mila and Pip are relieved as the vibrant futuristic world returns to normal.`,animation_prompt:`Show the world recovering in a glowing cinematic moment. Mila: "We did it, Pip!" Pip: "Teamwork always wins!" Camera rises toward warm sunlight and beautiful scenery.`},
    {scene_number:8,duration:15,scene_prompt:`Mila and Pip celebrate. Suddenly, ${twist}. A new mysterious doorway glimmers, promising tomorrow's adventure.`,animation_prompt:`Pip celebrates while Mila smiles. Suddenly ${twist}. Mila: "Pip, I think another adventure is waiting." Narrator: "What happens next?" End on a mysterious cinematic cliffhanger.`}
  ].map(s=>({...s,image_prompt:`${style}\n${s.scene_prompt}`,animation_prompt:`${style}\n${s.animation_prompt}`}));
  const title = `Mila and ${name} | Episode ${episodeNumber}`;
  const caption = `A new mystery appears for Mila and Pip! Today they discover ${discovery}. Can they save the future?\n\n#IfTomorrowBroke #AIAnimation #SciFi #Mystery #Shorts`;
  return [{json:{episode_id:`ITB-${String(episodeNumber).padStart(4,'0')}`,title,caption,series:'If Tomorrow Broke',total_duration:120,scene_count:8,scenes,scene_prompt:scenes[0].image_prompt,animation_prompt:scenes[0].animation_prompt}}];
})();

const source=$input.first().json;
if(!Array.isArray(source.scenes)||source.scenes.length!==8)throw new Error('Expected exactly 8 story scenes.');
if(!/^https:\/\//.test(source.reference_images?.[0]||''))throw new Error('Mila reference image missing.');
// Scenes 5 and 7 reuse matching landscape visuals (with new zoom/pan).
const selected=[1,2,3,4,6,8];
const clean=s=>String(s||'').replace(/\\n/g,' ').replace(/\s+/g,' ').trim();
return selected.map(scene_number=>{
 const scene=source.scenes[scene_number-1];
 const prompt=[
  'A SINGLE family-friendly cinematic 3D animation film still, portrait 9:16.',
  'Use the reference sheet only to keep the same girl Mila: same face, chestnut wavy hair, brown eyes, teal jacket, dark cargo pants, black boots, orange backpack.',
  'ONE Mila only, with her small friendly white-and-teal floating robot Pip, blue glowing eyes and orange accents.',
  'Create one new location/shot, not a multiple-view character turnaround sheet.',
  'SCENE: '+clean(scene.scene_prompt||scene.image_prompt),
  'Detailed environment, dramatic soft lighting, vibrant 3D family adventure, natural proportions, no text, no watermark, no duplicates.'
 ].join('\n\n');
 return {json:{scene_number,episode_id:source.episode_id,image_prompt:prompt,
   reference_images:source.reference_images}};
});

const r=$input.item.json;
const scene=$('Prepare Six Image Prompts').all()[$itemIndex]?.json;
if(r.code!==200||!r.data?.taskId||!scene)throw new Error('Image creation failed at scene '+(scene?.scene_number||$itemIndex+1)+': '+JSON.stringify(r));
return {json:{taskId:r.data.taskId,scene_number:scene.scene_number,episode_id:scene.episode_id,attempt:0}};

const obj=$input.first().json;
const rows=obj.data||[];
if(!Array.isArray(rows)||rows.length!==6)throw new Error('Missing one or more image task IDs.');
return rows.map(row=>({json:{taskId:row.taskId,scene_number:Number(row.scene_number),
  episode_id:row.episode_id,attempt:Number(obj.attempt??row.attempt??0)}}));

const rows=$input.all().map(item=>item.json);
if(rows.length!==6)throw new Error('Expected exactly 6 image status responses.');
const attempt=Math.max(...rows.map(r=>Number(r.attempt||0)))+1;
if(attempt>50)throw new Error('Image generation took too long.');
for(const row of rows){
 if(row.code!==200||!row.data)throw new Error('Image lookup failed for scene '+row.scene_number);
 if(['fail','failed','error'].includes(String(row.data.state).toLowerCase()))
   throw new Error('Image scene '+row.scene_number+' failed: '+(row.data.failMsg||row.data.failCode||''));
}
const ready=rows.every(r=>r.data.state==='success');
return [{json:{ready,attempt,data:rows}}];

const input=$input.first().json;
if(!input.ready||input.data?.length!==6)throw new Error('Image task batch is incomplete.');
return input.data.sort((a,b)=>a.scene_number-b.scene_number).map(row=>{
 const data=row.data||{};
 let result={};
 try{result=typeof data.resultJson==='string'?JSON.parse(data.resultJson):(data.resultJson||{});}
 catch(e){throw new Error('Invalid image result JSON for scene '+row.scene_number);}
 const image_url=result.resultUrls?.[0]||data.resultUrls?.[0];
 if(!/^https:\/\//.test(image_url||''))throw new Error('No generated image URL for scene '+row.scene_number);
 return {json:{scene_number:row.scene_number,image_url,episode_id:row.episode_id}};
});

const first=$input.all().find(i=>i.json.scene_number===1)?.json;
if(!first?.image_url)throw new Error('Missing scene one image.');
const story=$('Build Scene Prompt').first().json;
return [{json:{image_url:first.image_url,
  animation_prompt:'Cinematic family-friendly 3D animation. Mila in her teal jacket discovers a magical mirror. She looks surprised. Pip hovers gently. Smooth dolly-in camera, expressive eyes, same character appearance as the supplied image. Portrait vertical 9:16. No text, no character redesign.',
  episode_id:story.episode_id}}];

const r=$input.first().json;
if(r.code!==200||!r.data?.taskId)throw new Error('6-second Grok creation rejected: '+JSON.stringify(r));
return [{json:{taskId:r.data.taskId,attempt:0}}];

const row=$input.first().json;
if(row.code!==200||!row.data)throw new Error('Grok hook status request failed.');
if(['fail','failed','error'].includes(String(row.data.state).toLowerCase()))
  throw new Error('Grok hook generation failed: '+(row.data.failMsg||row.data.failCode||''));
const attempt=Number(row.attempt||0)+1;
if(attempt>80)throw new Error('Grok hook generation timed out.');
let video_url='';
if(row.data.state==='success'){
  let result={};
  try{result=typeof row.data.resultJson==='string'?JSON.parse(row.data.resultJson):(row.data.resultJson||{});}
  catch(e){throw new Error('Invalid Grok result JSON');}
  video_url=result.resultUrls?.[0]||row.data.resultUrls?.[0]||'';
  if(!/^https:\/\//.test(video_url))throw new Error('Grok completed but no video URL returned.');
}
return [{json:{ready:row.data.state==='success',attempt,video_url}}];

const hook=$input.first().json;
if(!hook.ready||!hook.video_url)throw new Error('Hook video not ready.');
const story=$('Build Scene Prompt').first().json;
const generated=$('Extract Six Images').all().map(i=>i.json);
if(generated.length!==6)throw new Error('Need six completed image URLs.');
const byNumber=new Map(generated.map(i=>[i.scene_number,i.image_url]));
const looks=[1,2,3,4,4,6,6,8];
const scenes=story.scenes.map((scene,index)=>{
 const image_url=byNumber.get(looks[index]);
 if(!image_url)throw new Error('Missing a reference visual for scene '+(index+1));
 const animation=String(scene.animation_prompt||'');
 const speech=Array.from(animation.matchAll(/(?:Narrator|Mila|Pip):\s*"([^"]+)"/g),m=>m[1]);
 const text=speech.join(' ')||String(scene.scene_prompt||'').trim().replace(/\s+/g,' ');
 const narration=text.split(/\s+/).slice(0,27).join(' ');
 const caption=String(scene.scene_prompt||'').replace(/\s+/g,' ').trim().split(/[.!?]/)[0].slice(0,83);
 return {image_url,narration,caption};
});
const run_id=(story.episode_id+'-'+Date.now()).replace(/[^a-zA-Z0-9-]/g,'-');
return [{json:{run_id,title:story.title,caption:story.caption,
  payload:{episode_id:story.episode_id,run_id,video_url:hook.video_url,
    hook_duration:6,scene_duration:15,scenes}}}];

const obj=$input.first().json;
const run_id=$('Build GitHub Render Payload').first().json.run_id;
const desired='mila-'+run_id;
const run=(obj.workflow_runs||[]).find(r=>r.display_title===desired);
const attempt=Number(obj.attempt||0)+1;
if(attempt>115)throw new Error('GitHub render timed out after nearly one hour.');
if(run?.status==='completed'&&run.conclusion!=='success')
  throw new Error('GitHub FFmpeg render failed. Open GitHub Actions run '+run.html_url);
return [{json:{ready:run?.status==='completed'&&run.conclusion==='success',
  attempt,github_run_id:run?.id||null,run_id}}];

const obj=$input.first().json;
const run_id=$('Build GitHub Render Payload').first().json.run_id;
const artifact=(obj.artifacts||[]).find(a=>a.name==='mila-'+run_id&&!a.expired);
if(!artifact?.archive_download_url)throw new Error('Rendered MP4 artifact was not found in GitHub Actions.');
return [{json:{archive_download_url:artifact.archive_download_url,run_id}}];

const item=$input.first();
const binary=item.binary||{};
const key=Object.keys(binary).find(k=>/\.mp4$/i.test(binary[k]?.fileName||''))||Object.keys(binary)[0];
if(!key||!binary[key])throw new Error('No MP4 binary in GitHub artifact ZIP.');
const info=$('Build GitHub Render Payload').first().json;
return [{json:{title:info.title,caption:info.caption,run_id:info.run_id},binary:{data:binary[key]}}];

const result=$input.first().json;
const id=result.id||result.videoId||result.data?.id;
if(!id||typeof id!=='string')throw new Error('YouTube did not confirm a video ID.');
const episode=$('Build GitHub Render Payload').first().json;
return [{json:{title:episode.title,caption:episode.caption,
  videoUrl:'https://www.youtube.com/watch?v='+id,episode_id:episode.payload.episode_id}}];

